head.script:
/* =====================================================================
 * KHÁCH MỜI - DANH SÁCH, TÌM KIẾM, THÊM / SỬA / XÓA, CHI TIẾT, EXPORT
 * API: /api/guests (xem API_GUEST.md)
 * ===================================================================== */
scwin.P = "gs";
/* =====================================================================
 * LỚP DÙNG CHUNG (giống các màn Hội trường / Sự kiện)
 *   - Phiên đăng nhập, quyền
 *   - Gọi API JSON bằng submission WebSquare (scwin.callApi)
 *   - Upload / tải file bằng XMLHttpRequest (submission không xử lý file nhị phân)
 * ===================================================================== */
scwin.API_BASE = "http://localhost:8081";
scwin.KEY = { TOKEN: "ssc_token", USER: "ssc_user", PERMS: "ssc_permissions", MENUS: "ssc_menus" };
scwin.LOGIN_PAGE = "/authPage/LoginPage.xml";
scwin.CTX = window.location.pathname.replace(/\/websquare\/websquare\.html.*$/, "");
scwin.SBM_TIMEOUT = 60000;
scwin.sbmQueue = {};
scwin.sbmJob = {};
scwin.toastTimer = null;

/* ---------- Tiện ích ---------- */
scwin.comp = function (id) { return $p.getComponentById(id); };
scwin.domOf = function (c) { return c ? (c.render || document.getElementById(c.id) || null) : null; };
scwin.show = function (c, v) { if (!c) return; if (v === false) c.addClass("is-hidden"); else c.removeClass("is-hidden"); };
scwin.toggleClass = function (c, cls, on) { if (!c) return; if (on) c.addClass(cls); else c.removeClass(cls); };
scwin.safeColor = function (c) { return /^#[0-9a-f]{3,8}$/i.test(String(c || "")) ? c : "#63746b"; };
scwin.trim = function (v) { return v == null ? "" : String(v).replace(/^\s+|\s+$/g, ""); };
scwin.dash = function (v) { return (v == null || scwin.trim(v) === "") ? "—" : String(v); };
scwin.pad = function (n) { return n < 10 ? "0" + n : String(n); };
scwin.clamp = function (v, a, b) { v = Number(v) || 0; a = a == null ? 0 : a; b = b == null ? 100 : b; return Math.max(a, Math.min(b, v)); };
scwin.hasOwn = function (o, k) { return o != null && Object.prototype.hasOwnProperty.call(o, k); };
scwin.fmtNumber = function (n) { return (n == null || n === "" || isNaN(Number(n))) ? "—" : Number(n).toLocaleString("vi-VN"); };
scwin.fmtRate = function (r) { return (Math.round((Number(r) || 0) * 10) / 10).toLocaleString("vi-VN") + "%"; };
scwin.fmtDate = function (s) { if (!s) return ""; var p = String(s).substring(0, 10).split("-"); return p.length === 3 ? p[2] + "/" + p[1] + "/" + p[0] : String(s); };
scwin.fmtTime = function (s) { return s ? String(s).substring(0, 5) : ""; };
scwin.fmtDateTime = function (iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    return scwin.pad(d.getDate()) + "/" + scwin.pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes());
};
scwin.fmtClock = function (iso) {
    var d = iso ? new Date(iso) : new Date();
    if (isNaN(d.getTime())) d = new Date();
    return scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes()) + ":" + scwin.pad(d.getSeconds());
};
scwin.fmtSize = function (b) { return b >= 1048576 ? (b / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1024)) + " KB"; };
/** Tham số mảng được nối bằng dấu phẩy (backend nhận cả "A,B" lẫn lặp tham số). */
scwin.buildQuery = function (p) {
    var out = [];
    for (var k in p) {
        if (!p.hasOwnProperty(k)) continue;
        var v = p[k];
        if (Array.isArray(v)) { if (!v.length) continue; v = v.join(","); }
        if (v === null || v === undefined || v === "") continue;
        out.push(encodeURIComponent(k) + "=" + encodeURIComponent(v));
    }
    return out.join("&");
};
scwin.getQueryParam = function (name) {
    var m = new RegExp("[?&]" + name + "=([^&#]*)").exec(window.location.search);
    return m ? decodeURIComponent(m[1].replace(/\+/g, " ")) : "";
};
scwin.pageUrl = function (path, params) {
    var q = params ? scwin.buildQuery(params) : "";
    return scwin.CTX + "/websquare/websquare.html?w2xPath=" + scwin.CTX + path + (q ? "&" + q : "");
};
scwin.escHtml = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); };
scwin.el = function (tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
scwin.clearEl = function (el) { if (el) while (el.firstChild) el.removeChild(el.firstChild); };
scwin.fitGrid = function (grid, rows, rowH, maxRows) {
    var n = maxRows ? Math.min(rows, maxRows) : rows;
    grid.setStyle("height", (rows ? 42 + n * (rowH || 46) + 2 : 0) + "px");
    scwin.show(grid, rows > 0);
};
scwin.isTrue = function (v) { return v === true || v === "true" || v === 1 || v === "1"; };

/* ---------- Phiên đăng nhập & quyền ---------- */
scwin.storeGet = function (k) { try { return window.localStorage.getItem(k) || window.sessionStorage.getItem(k) || ""; } catch (e) { return ""; } };
scwin.parseJSON = function (t) { if (!t || typeof t !== "string") return null; try { return JSON.parse(t); } catch (e) { return null; } };
scwin.getToken = function () { return String(scwin.storeGet(scwin.KEY.TOKEN)).replace(/^Bearer\s+/i, ""); };
scwin.getPerms = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.PERMS)) || []; };
scwin.getUser = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.USER)) || {}; };
/** Header chưa kịp lưu quyền (lần đầu vào trang) thì tạm cho phép; backend vẫn chặn bằng 403. */
scwin.can = function (code) { var p = scwin.getPerms(); return !p.length || p.indexOf(code) >= 0; };
scwin.canAny = function (codes) { for (var i = 0; i < codes.length; i++) if (scwin.can(codes[i])) return true; return false; };
scwin.goLogin = function () {
    if (scwin._redirecting) return;
    scwin._redirecting = true;
    for (var k in scwin.KEY) {
        if (!scwin.KEY.hasOwnProperty(k)) continue;
        try { window.localStorage.removeItem(scwin.KEY[k]); window.sessionStorage.removeItem(scwin.KEY[k]); } catch (e) { }
    }
    window.location.href = scwin.pageUrl(scwin.LOGIN_PAGE);
};

/* ---------- Lỗi ---------- */
scwin.defaultMessage = function (status) {
    if (status === 0) return "Không kết nối được máy chủ. Kiểm tra mạng hoặc backend (" + scwin.API_BASE + ").";
    if (status === 401) return "Phiên đăng nhập đã hết hạn. Hãy đăng nhập lại.";
    if (status === 403) return "Tài khoản của bạn chưa được cấp quyền cho thao tác này.";
    if (status === 404) return "Không tìm thấy dữ liệu, hoặc dữ liệu nằm ngoài phạm vi bạn được xem.";
    if (status >= 500) return "Máy chủ đang gặp sự cố. Thử lại sau ít phút.";
    return "Yêu cầu không thành công (HTTP " + status + ").";
};
scwin.authHeader = function (accept) {
    var h = { "Accept": accept || "application/json" };
    var t = scwin.getToken();
    if (t) h["Authorization"] = "Bearer " + t;
    return h;
};
/** Chuẩn hóa lỗi: { status, code, message, data }. 401 thì đưa về trang đăng nhập. */
scwin.buildError = function (status, json) {
    var err = {
        status: status || 0,
        code: (json && json.code) || (status ? "HTTP_" + status : "NETWORK_ERROR"),
        message: (json && json.message) || scwin.defaultMessage(status || 0),
        data: json ? json.data : null
    };
    if (status === 401) {
        err.message = scwin.defaultMessage(401);
        scwin.toast(err.message + " Đang chuyển về trang đăng nhập…", "error");
        setTimeout(scwin.goLogin, 1500);
    }
    return err;
};

/* ---------- Submission ----------
 *   scwin.callApi("sbm_xxx", { url: "...", body: {...} }) -> Promise<data>
 *   Mỗi submission có hàng đợi riêng nên gọi chồng nhau không bị trả nhầm kết quả.
 */
scwin.callApi = function (sbmId, opts) {
    return new Promise(function (resolve, reject) {
        if (!scwin.sbmQueue[sbmId]) scwin.sbmQueue[sbmId] = [];
        scwin.sbmQueue[sbmId].push({ opts: opts || {}, resolve: resolve, reject: reject });
        scwin.sbmNext(sbmId);
    });
};
scwin.sbmNext = function (sbmId) {
    if (scwin.sbmJob[sbmId]) return;
    var q = scwin.sbmQueue[sbmId];
    if (!q || !q.length) return;
    var job = q.shift();
    scwin.sbmJob[sbmId] = job;
    var sbm = $p.getSubmission(sbmId);
    if (!sbm) { scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_NOT_FOUND", message: "Chưa khai báo submission " + sbmId + "." }); return; }
    sbm.action = job.opts.url;
    sbm.requestHeader = scwin.authHeader();
    job.timer = setTimeout(function () {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "TIMEOUT", message: "Máy chủ phản hồi quá lâu. Thử lại sau." });
    }, scwin.SBM_TIMEOUT);
    try {
        if (job.opts.body !== undefined) $p.executeSubmission(sbmId, job.opts.body);
        else $p.executeSubmission(sbmId);
    } catch (ex) {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_ERROR", message: (ex && ex.message) || String(ex) });
    }
};
scwin.sbmSettle = function (sbmId, data, err) {
    var job = scwin.sbmJob[sbmId];
    if (!job) return;
    clearTimeout(job.timer);
    scwin.sbmJob[sbmId] = null;
    if (err) job.reject(err); else job.resolve(data);
    scwin.sbmNext(sbmId);
};
scwin.readResponse = function (e) {
    if (!e) return null;
    if (e.responseJSON && typeof e.responseJSON === "object") return e.responseJSON;
    return scwin.parseJSON(e.responseText) || scwin.parseJSON(e.responseBody);
};
scwin.onSbmDone = function (sbmId, e) {
    var json = scwin.readResponse(e);
    if (json && json.success === false) { scwin.sbmSettle(sbmId, null, scwin.buildError((e && e.responseStatusCode) || 200, json)); return; }
    scwin.sbmSettle(sbmId, scwin.hasOwn(json, "data") ? json.data : json, null);
};
scwin.onSbmError = function (sbmId, e) {
    var status = (e && (e.responseStatusCode || e.status)) || 0;
    scwin.sbmSettle(sbmId, null, scwin.buildError(status, scwin.readResponse(e)));
};

/* ---------- XMLHttpRequest: upload multipart, nhận file ----------
 *   opts.body: object (gửi JSON) | FormData (multipart)
 *   opts.responseType: "json" (mặc định) | "blob" -> resolve { blob, name, type, headers }
 */
scwin.xhr = function (method, url, opts) {
    opts = opts || {};
    return new Promise(function (resolve, reject) {
        var x = new XMLHttpRequest();
        x.open(method, url);
        var h = scwin.authHeader(opts.responseType === "blob" ? "*/*" : "application/json");
        for (var k in h) if (h.hasOwnProperty(k)) x.setRequestHeader(k, h[k]);
        var body = null;
        if (typeof FormData !== "undefined" && opts.body instanceof FormData) body = opts.body;
        else if (opts.body !== undefined && opts.body !== null) { x.setRequestHeader("Content-Type", "application/json"); body = JSON.stringify(opts.body); }
        if (opts.responseType === "blob") x.responseType = "blob";
        if (opts.onProgress && x.upload) x.upload.onprogress = function (ev) { if (ev.lengthComputable) opts.onProgress(Math.round(ev.loaded * 100 / ev.total)); };
        x.onload = function () {
            var ok = x.status >= 200 && x.status < 300;
            if (opts.responseType === "blob") {
                var type = x.getResponseHeader("Content-Type") || "";
                if (ok && type.indexOf("application/json") < 0) {
                    resolve({ blob: x.response, type: type, name: scwin.fileNameFrom(x.getResponseHeader("Content-Disposition")), xhr: x });
                    return;
                }
                scwin.readBlobJSON(x.response).then(function (json) { reject(scwin.buildError(ok ? 200 : x.status, json)); });
                return;
            }
            var json = scwin.parseJSON(x.responseText);
            if (ok && !(json && json.success === false)) resolve(scwin.hasOwn(json, "data") ? json.data : json);
            else reject(scwin.buildError(x.status, json));
        };
        x.onerror = function () { reject(scwin.buildError(0, null)); };
        x.send(body);
    });
};
scwin.readBlobJSON = function (blob) {
    return new Promise(function (resolve) {
        if (!blob || typeof FileReader === "undefined") { resolve(null); return; }
        var r = new FileReader();
        r.onload = function () { resolve(scwin.parseJSON(r.result)); };
        r.onerror = function () { resolve(null); };
        r.readAsText(blob);
    });
};
scwin.fileNameFrom = function (cd) {
    if (!cd) return "";
    var m = /filename\*=UTF-8''([^;]+)/i.exec(cd) || /filename="?([^";]+)"?/i.exec(cd);
    if (!m) return "";
    try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
};
scwin.saveBlob = function (blob, name) {
    var url = URL.createObjectURL(blob);
    var a = scwin.el("a", scwin.P + "-native-link");
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(url); if (a.parentNode) a.parentNode.removeChild(a); }, 1500);
};
/** Tải file (GET hoặc POST kèm body JSON) rồi lưu về máy. */
scwin.downloadFile = function (url, fallbackName, btn, method, body) {
    if (btn) btn.addClass("is-busy");
    return scwin.xhr(method || "GET", url, { responseType: "blob", body: body }).then(function (r) {
        scwin.saveBlob(r.blob, r.name || fallbackName);
        return r;
    }).catch(function (err) {
        scwin.toast(err.message, "error");
        throw err;
    }).then(function (r) { if (btn) btn.removeClass("is-busy"); return r; }, function () { if (btn) btn.removeClass("is-busy"); });
};
/** In file PDF: nạp vào iframe ẩn rồi mở hộp thoại in của trình duyệt. */
scwin.printBlob = function (blob) {
    return new Promise(function (resolve) {
        var old = document.getElementById("ssc-print-frame");
        if (old) old.parentNode.removeChild(old);
        var url = URL.createObjectURL(blob);
        var f = document.createElement("iframe");
        f.id = "ssc-print-frame";
        f.className = scwin.P + "-print-frame";
        f.src = url;
        f.onload = function () {
            setTimeout(function () {
                try { f.contentWindow.focus(); f.contentWindow.print(); }
                catch (e) { window.open(url, "_blank"); }
                resolve();
            }, 300);
        };
        document.body.appendChild(f);
    });
};

/* ---------- Thông báo ---------- */
scwin.toast = function (msg, type) {
    if (typeof tbx_toast === "undefined") return;
    clearTimeout(scwin.toastTimer);
    tbx_toast.setValue(msg || "");
    ["success", "error", "warning", "info"].forEach(function (c) { tbx_toast.removeClass(scwin.P + "-toast--" + c); });
    tbx_toast.addClass(scwin.P + "-toast--" + (type || "info"));
    tbx_toast.addClass("is-show");
    scwin.toastTimer = setTimeout(function () { tbx_toast.removeClass("is-show"); }, (type === "error" || type === "warning") ? 6500 : 3800);
};
scwin.tbx_toast_onclick = function () { tbx_toast.removeClass("is-show"); };
scwin.showWarnings = function (list) {
    if (!list || !list.length) return;
    setTimeout(function () { scwin.toast("Lưu ý: " + list.join(" "), "warning"); }, 1800);
};

/* ---------- Danh mục dùng chung: GET /api/guests/lookups ---------- */
scwin.lookups = { events: [], guestTypes: [], guestStatuses: [] };
scwin.typeMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestTypes.length; i++) if (scwin.lookups.guestTypes[i].code === code) return scwin.lookups.guestTypes[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.statusMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestStatuses.length; i++) if (scwin.lookups.guestStatuses[i].code === code) return scwin.lookups.guestStatuses[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.GUEST_TYPE_VN = { VIP: "VIP", SPEAKER: "Diễn giả", GUEST: "Khách mời", STAFF: "Nhân viên", PRESS: "Báo chí", OTHER: "Khác" };
scwin.GUEST_STATUS_VN = { INVITED: "Đã mời", CONFIRMED: "Đã xác nhận", CHECKED_IN: "Đã check-in", ABSENT: "Vắng mặt" };
scwin.typeName = function (code) { return scwin.GUEST_TYPE_VN[code] || scwin.typeMeta(code).name; };
scwin.statusName = function (code) { return scwin.GUEST_STATUS_VN[code] || scwin.statusMeta(code).name; };
scwin.eventLabel = function (e) { return e.eventCode + " - " + e.eventName + (e.startDate ? " (" + scwin.fmtDate(e.startDate) + ")" : ""); };


/* ---------- Cấu hình màn hình ---------- */
scwin.GUEST_API = scwin.API_BASE + "/api/guests";
scwin.PRINT_API = scwin.API_BASE + "/api/print";
scwin.IMPORT_PAGE = "/guestPage/GuestImport.xml";
scwin.PRINT_PAGE = "/printPage/PrintCenter.xml";
scwin.HANDOFF_KEY = "ssc_print_handoff";        // chuyển danh sách khách đã chọn sang Trung tâm in
scwin.PHOTO_TYPES = ["image/jpeg", "image/png"];
scwin.PHOTO_MAX = 2 * 1024 * 1024;

scwin.SEARCH_DEFAULT = {
    eventId: "", keyword: "", fullName: "", email: "", phone: "", company: "", tableNumber: "",
    checkedIn: "", badgePrinted: "", nameplacePrinted: "", sort: "fullName,asc", size: "20", page: "0"
};
scwin.state = { typeCodes: [], statusCodes: [], importBatchId: "", totalPages: 0, totalElements: 0, advOpen: false };
scwin.selected = {};                  // guestId -> dòng đã chọn (giữ qua các trang)
scwin.current = null;                 // chi tiết khách đang mở
scwin.tab = "info";
scwin.open = { drawer: false, form: false, bulk: false, del: false, exp: false, note: false, confirm: false };
scwin.form = { mode: "create", guestId: null, origStatus: "", dirty: false, saving: false, keepOpen: false };
scwin.searchSeq = 0;
scwin.timers = {};
scwin.cfm = null;
scwin.note = null;
scwin.delList = [];

scwin.FIELDS = {
    eventId:       { input: "sbx_fEvent",    error: "tbx_fEventErr",   label: "Sự kiện" },
    fullName:      { input: "ibx_fName",     error: "tbx_fNameErr",    label: "Họ và tên", max: 150 },
    email:         { input: "ibx_fEmail",    error: "tbx_fEmailErr",   label: "Email", max: 255 },
    phone:         { input: "ibx_fPhone",    error: "tbx_fPhoneErr",   label: "Số điện thoại" },
    company:       { input: "ibx_fCompany",  error: "tbx_fCompanyErr", label: "Công ty / Tổ chức", max: 255 },
    position:      { input: "ibx_fPosition", error: "tbx_fPositionErr",label: "Chức vụ", max: 150 },
    guestTypeCode: { input: "sbx_fType",     error: "tbx_fTypeErr",    label: "Loại khách" },
    tableNumber:   { input: "ibx_fTable",    error: "tbx_fTableErr",   label: "Bàn số", max: 20 },
    statusCode:    { input: "sbx_fStatus",   error: "tbx_fStatusErr",  label: "Trạng thái" },
    notes:         { input: "txa_fNotes",    error: "tbx_fNotesErr",   label: "Ghi chú", max: 2000 }
};
scwin.TABS = { info: ["btn_tabInfo", "grp_pInfo"], qr: ["btn_tabQr", "grp_pQr"], checkins: ["btn_tabCheckins", "grp_pCheckins"], prints: ["btn_tabPrints", "grp_pPrints"] };
scwin.METHOD_VN = { QR_CAMERA: "Quét camera", QR_UPLOAD: "Ảnh QR", MANUAL: "Thủ công" };
scwin.RESULT_VN = { SUCCESS: "Thành công", ALREADY_CHECKED_IN: "Đã check-in trước", INVALID_QR: "QR không hợp lệ", WRONG_EVENT: "Sai sự kiện", GUEST_NOT_FOUND: "Không có khách", EVENT_NOT_ACTIVE: "Sự kiện chưa mở" };
scwin.PRINT_TYPE_VN = { NAMECARD: "Thẻ tên", NAMEPLACE: "Danh bạ để bàn" };
scwin.EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
scwin.PHONE_RE = /^\+?[0-9 .()\-]{8,20}$/;

/* =====================================================================
 * VÒNG ĐỜI
 * ===================================================================== */
scwin.onpageload = function () {
    if (!scwin.getToken()) { scwin.goLogin(); return; }
    scwin.keyHandler = function (e) { scwin.onGlobalKeydown(e); };
    document.addEventListener("keydown", scwin.keyHandler);
    scwin.initFileInput();

    var q = {};
    for (var k in scwin.SEARCH_DEFAULT) if (scwin.SEARCH_DEFAULT.hasOwnProperty(k)) q[k] = scwin.SEARCH_DEFAULT[k];
    q.eventId = scwin.getQueryParam("eventId");
    dma_search.setJSON(q);
    scwin.state.importBatchId = scwin.getQueryParam("importBatchId");

    scwin.applyPermissions();
    scwin.renderChips();
    scwin.loadLookups();
    scwin.search(true);
    var gid = scwin.getQueryParam("guestId");
    if (gid) scwin.openDetail(gid);
};
scwin.onpageunload = function () { document.removeEventListener("keydown", scwin.keyHandler); };

scwin.applyPermissions = function () {
    scwin.show(btn_add, scwin.can("GUEST_CREATE"));
    scwin.show(btn_import, scwin.can("GUEST_IMPORT"));
    scwin.show(btn_export, scwin.can("GUEST_EXPORT"));
    scwin.show(btn_bulkEdit, scwin.can("GUEST_UPDATE"));
    scwin.show(btn_bulkDelete, scwin.can("GUEST_DELETE"));
    scwin.show(btn_bulkPrint, scwin.can("PRINT_BADGE"));
    scwin.show(btn_dEdit, scwin.can("GUEST_UPDATE"));
    scwin.show(btn_dDelete, scwin.can("GUEST_DELETE"));
    scwin.show(btn_dPrint, scwin.can("PRINT_BADGE"));
    scwin.show(grp_photoActions, scwin.can("GUEST_UPDATE"));
    scwin.show(btn_qrRegen, scwin.can("GUEST_UPDATE"));
};

/* =====================================================================
 * DANH MỤC
 * ===================================================================== */
scwin.loadLookups = function () {
    return scwin.callApi("sbm_lookups", { url: scwin.GUEST_API + "/lookups" }).then(function (d) {
        d = d || {};
        scwin.lookups.events = d.events || [];
        scwin.lookups.guestTypes = d.guestTypes || [];
        scwin.lookups.guestStatuses = d.guestStatuses || [];
        dlt_events.setJSON(scwin.lookups.events.map(function (e) { return { eventId: String(e.eventId), label: scwin.eventLabel(e), statusCode: e.statusCode }; }));
        dlt_types.setJSON(scwin.lookups.guestTypes.map(function (t) { return { code: t.code, name: scwin.typeName(t.code) }; }));
        dlt_statuses.setJSON(scwin.lookups.guestStatuses.map(function (s) { return { code: s.code, name: scwin.statusName(s.code) }; }));
        sbx_event.setValue(dma_search.get("eventId") || "");
        scwin.renderChips();
    }).catch(function (err) { scwin.toast("Không tải được danh mục: " + err.message, "warning"); });
};

/** Chip chọn nhiều cho Trạng thái và Loại khách (màu lấy từ backend). */
scwin.renderChips = function () {
    scwin.renderChipGroup(grp_statusChips, scwin.lookups.guestStatuses.length ? scwin.lookups.guestStatuses : ["INVITED", "CONFIRMED", "CHECKED_IN", "ABSENT"].map(scwin.statusMeta), "statusCodes", scwin.statusName);
    scwin.renderChipGroup(grp_typeChips, scwin.lookups.guestTypes, "typeCodes", scwin.typeName);
};
scwin.renderChipGroup = function (comp, list, key, nameFn) {
    var box = scwin.domOf(comp);
    if (!box) return;
    scwin.clearEl(box);
    var sel = scwin.state[key];
    list.forEach(function (it) {
        var on = sel.indexOf(it.code) >= 0;
        var chip = scwin.el("button", "gs-chip" + (on ? " is-selected" : ""), nameFn(it.code));
        chip.type = "button";
        chip.setAttribute("aria-pressed", on ? "true" : "false");
        chip.style.setProperty("--gs-status", scwin.safeColor(it.color));
        chip.addEventListener("click", function () {
            var i = scwin.state[key].indexOf(it.code);
            if (i >= 0) scwin.state[key].splice(i, 1); else scwin.state[key].push(it.code);
            scwin.renderChips();
            scwin.search(true);
        });
        box.appendChild(chip);
    });
};

/* =====================================================================
 * TÌM KIẾM & DANH SÁCH
 * ===================================================================== */
scwin.collectFilter = function (forExport) {
    var q = dma_search.getJSON(), t = scwin.trim;
    var p = {
        eventId: q.eventId, keyword: t(q.keyword),
        fullName: t(q.fullName), email: t(q.email), phone: t(q.phone), company: t(q.company), tableNumber: t(q.tableNumber),
        guestTypeCodes: scwin.state.typeCodes, statusCodes: scwin.state.statusCodes,
        checkedIn: q.checkedIn, badgePrinted: q.badgePrinted, nameplacePrinted: q.nameplacePrinted,
        importBatchId: scwin.state.importBatchId, sort: q.sort || "fullName,asc"
    };
    if (!forExport) { p.page = q.page || "0"; p.size = q.size || "20"; }
    return p;
};

scwin.hasFilter = function () {
    var p = scwin.collectFilter(true);
    return !!(p.keyword || p.fullName || p.email || p.phone || p.company || p.tableNumber || p.guestTypeCodes.length
        || p.statusCodes.length || p.checkedIn || p.badgePrinted || p.nameplacePrinted || p.importBatchId);
};

scwin.search = function (resetPage) {
    if (resetPage) dma_search.set("page", "0");
    var params = scwin.collectFilter(false);
    scwin.updateFilterSummary(params);
    var seq = ++scwin.searchSeq;
    grp_listBody.addClass("is-loading");
    scwin.callApi("sbm_guestList", { url: scwin.GUEST_API + "?" + scwin.buildQuery(params) }).then(function (page) {
        if (seq === scwin.searchSeq) scwin.renderList(page || {});
    }).catch(function (err) {
        if (seq !== scwin.searchSeq) return;
        scwin.renderList({ content: [] });
        scwin.toast(err.message, "error");
    }).then(function () { if (seq === scwin.searchSeq) grp_listBody.removeClass("is-loading"); });
};

scwin.renderList = function (page) {
    var content = page.content || [];
    var cur = parseInt(dma_search.get("page"), 10) || 0, size = parseInt(dma_search.get("size"), 10) || 20;
    scwin.state.totalPages = page.totalPages || 0;
    scwin.state.totalElements = page.totalElements || 0;
    if (!content.length && cur > 0 && scwin.state.totalPages > 0) {
        dma_search.set("page", String(scwin.state.totalPages - 1));
        scwin.search(false);
        return;
    }
    dlt_guest.setJSON(content.map(function (g) {
        var r = {};
        for (var k in g) if (g.hasOwnProperty(k)) r[k] = g[k];
        r.chk = scwin.selected[g.guestId] ? "1" : "0";
        r.actEdit = ""; r.actDelete = ""; r.actPrint = "";
        return r;
    }));
    for (var i = 0; i < content.length; i++) {
        try {
            grd_guest.setCellClass(i, "guestTypeCode", "gs-gtype gs-gtype--" + content[i].guestTypeCode);
            grd_guest.setCellClass(i, "statusCode", "gs-gst gs-gst--" + content[i].statusCode);
        } catch (e) { }
    }
    var empty = !content.length;
    scwin.show(grp_empty, empty);
    scwin.toggleClass(grp_listBody, "is-empty", empty);
    if (empty) {
        var f = scwin.hasFilter();
        tbx_emptyTitle.setValue(f ? "Không có khách khớp bộ lọc" : "Chưa có khách mời");
        tbx_emptyDesc.setValue(f ? "Thử bỏ bớt điều kiện tìm kiếm." : "Thêm khách thủ công hoặc import từ file Excel.");
        scwin.show(btn_emptyReset, f);
        scwin.show(grp_emptyAdd, !f && scwin.canAny(["GUEST_CREATE", "GUEST_IMPORT"]));
    }
    var from = empty ? 0 : cur * size + 1;
    tbx_resultInfo.setValue(empty ? "Không có kết quả" : "Hiển thị " + from + "–" + (from + content.length - 1) + " trong " + scwin.fmtNumber(scwin.state.totalElements) + " khách");
    scwin.pagingLock = true;
    try { pgl_guest.setCount(Math.max(scwin.state.totalPages, 1)); pgl_guest.setSelectedIndex(cur + 1); } catch (e) { }
    scwin.pagingLock = false;
    scwin.show(grp_pager, scwin.state.totalPages > 1);
    scwin.renderBulkBar();
};

scwin.updateFilterSummary = function (p) {
    var parts = [];
    if (p.keyword) parts.push("“" + p.keyword + "”");
    if (p.fullName) parts.push("tên: " + p.fullName);
    if (p.email) parts.push("email: " + p.email);
    if (p.phone) parts.push("SĐT: " + p.phone);
    if (p.company) parts.push("công ty: " + p.company);
    if (p.tableNumber) parts.push("bàn " + p.tableNumber);
    if (p.statusCodes.length) parts.push(p.statusCodes.map(scwin.statusName).join(", ").toLowerCase());
    if (p.guestTypeCodes.length) parts.push(p.guestTypeCodes.map(scwin.typeName).join(", "));
    if (p.checkedIn) parts.push(p.checkedIn === "true" ? "đã check-in" : "chưa check-in");
    if (p.badgePrinted) parts.push(p.badgePrinted === "true" ? "đã in thẻ" : "chưa in thẻ");
    if (p.nameplacePrinted) parts.push(p.nameplacePrinted === "true" ? "đã in danh bạ" : "chưa in danh bạ");
    if (p.importBatchId) parts.push("lần import #" + p.importBatchId);
    tbx_filterSummary.setValue(parts.length ? "Đang lọc: " + parts.join("; ") : "");
    scwin.show(tbx_filterSummary, parts.length > 0);
    scwin.show(btn_reset, parts.length > 0);
    var advCount = ["fullName", "email", "phone", "company", "tableNumber", "badgePrinted", "nameplacePrinted"].filter(function (k) { return !!p[k]; }).length;
    btn_advToggle.setValue(advCount ? "Tìm nâng cao (" + advCount + ")" : "Tìm nâng cao");
};

/* ---------- Formatter cột ---------- */
scwin.row = function (i) { return dlt_guest.getRowJSON(i) || {}; };
scwin.gfName = function (v, f, i) {
    var r = scwin.row(i);
    return dma_search.get("eventId") ? v : v + "   " + (r.eventCode || "");
};
scwin.gfDash = function (v) { return scwin.dash(v); };
scwin.gfType = function (v) { return scwin.typeName(v); };
scwin.gfStatus = function (v, f, i) {
    var r = scwin.row(i);
    return "● " + scwin.statusName(v) + (r.checkInTime && v === "CHECKED_IN" ? " " + scwin.fmtClock(r.checkInTime).substr(0, 5) : "");
};
scwin.gfActEdit = function () { return scwin.can("GUEST_UPDATE") ? "Sửa" : ""; };
scwin.gfActDelete = function () { return scwin.can("GUEST_DELETE") ? "Xóa" : ""; };
scwin.gfActPrint = function () { return scwin.can("PRINT_BADGE") ? "In thẻ" : ""; };
scwin.gfDateTime = function (v) { return v ? scwin.fmtDateTime(v) : "—"; };

/* ---------- Sự kiện bộ lọc ---------- */
scwin.debounce = function (key, fn, ms) { clearTimeout(scwin.timers[key]); scwin.timers[key] = setTimeout(fn, ms); };
scwin.syncInput = function (comp, key) { var v = comp.getValue(); if (dma_search.get(key) !== v) dma_search.set(key, v); };
scwin.ibx_keyword_onkeyup = function (e) {
    scwin.syncInput(ibx_keyword, "keyword");
    if (e && e.keyCode === 13) { clearTimeout(scwin.timers.s); scwin.search(true); return; }
    scwin.debounce("s", function () { scwin.search(true); }, 400);
};
scwin.adv_onkeyup = function (e) {
    [["fullName", ibx_aName], ["email", ibx_aEmail], ["phone", ibx_aPhone], ["company", ibx_aCompany], ["tableNumber", ibx_aTable]]
        .forEach(function (p) { scwin.syncInput(p[1], p[0]); });
    if (e && e.keyCode === 13) { clearTimeout(scwin.timers.s); scwin.search(true); return; }
    scwin.debounce("s", function () { scwin.search(true); }, 500);
};
scwin.sbx_event_onchange = function () { dma_search.set("eventId", sbx_event.getValue() || ""); scwin.search(true); };
scwin.sbx_checked_onchange = function () { dma_search.set("checkedIn", sbx_checked.getValue() || ""); scwin.search(true); };
scwin.sbx_aBadge_onchange = function () { dma_search.set("badgePrinted", sbx_aBadge.getValue() || ""); scwin.search(true); };
scwin.sbx_aPlace_onchange = function () { dma_search.set("nameplacePrinted", sbx_aPlace.getValue() || ""); scwin.search(true); };
scwin.sbx_sort_onchange = function () { dma_search.set("sort", sbx_sort.getValue() || "fullName,asc"); scwin.search(true); };
scwin.sbx_size_onchange = function () { dma_search.set("size", sbx_size.getValue() || "20"); scwin.search(true); };
scwin.btn_advToggle_onclick = function () {
    scwin.state.advOpen = !scwin.state.advOpen;
    scwin.toggleClass(grp_adv, "is-open", scwin.state.advOpen);
    scwin.toggleClass(btn_advToggle, "is-active", scwin.state.advOpen);
    if (scwin.state.advOpen) setTimeout(function () { try { ibx_aName.focus(); } catch (e) { } }, 80);
};
scwin.btn_advApply_onclick = function () { scwin.adv_onkeyup({ keyCode: 13 }); };
scwin.btn_reset_onclick = function () {
    var q = dma_search.getJSON();
    var d = {};
    for (var k in scwin.SEARCH_DEFAULT) if (scwin.SEARCH_DEFAULT.hasOwnProperty(k)) d[k] = scwin.SEARCH_DEFAULT[k];
    d.eventId = q.eventId; d.sort = q.sort; d.size = q.size;
    dma_search.setJSON(d);
    scwin.state.typeCodes = []; scwin.state.statusCodes = []; scwin.state.importBatchId = "";
    scwin.renderChips();
    scwin.search(true);
};
scwin.btn_emptyReset_onclick = scwin.btn_reset_onclick;
scwin.btn_refresh_onclick = function () { scwin.search(false); if (scwin.open.drawer && scwin.current) scwin.openDetail(scwin.current.guestId); };
scwin.pgl_guest_onviewchange = function (info) {
    if (scwin.pagingLock) return;
    var idx = (info && info.newSelectedIndex) ? info.newSelectedIndex : pgl_guest.getSelectedIndex();
    dma_search.set("page", String(Math.max(0, idx - 1)));
    scwin.search(false);
};

/* =====================================================================
 * CHỌN NHIỀU (cột checkbox của grid) & THAO TÁC HÀNG LOẠT
 * ===================================================================== */
scwin.syncSelection = function () {
    var n = dlt_guest.getRowCount();
    for (var i = 0; i < n; i++) {
        var r = dlt_guest.getRowJSON(i);
        if (!r || !r.guestId) continue;
        if (r.chk === "1" || r.chk === 1 || r.chk === true) {
            scwin.selected[r.guestId] = { guestId: r.guestId, fullName: r.fullName, eventId: r.eventId, checkedIn: scwin.isTrue(r.checkedIn) };
        } else {
            delete scwin.selected[r.guestId];
        }
    }
    scwin.renderBulkBar();
};
scwin.dlt_guest_oncelldatachange = function (info) {
    if (info && info.colID && info.colID !== "chk") return;
    scwin.debounce("sel", scwin.syncSelection, 60);
};
scwin.grd_guest_onheaderclick = function () { scwin.debounce("sel", scwin.syncSelection, 80); };

scwin.selectedList = function () {
    var out = [];
    for (var k in scwin.selected) if (scwin.selected.hasOwnProperty(k)) out.push(scwin.selected[k]);
    return out;
};
scwin.renderBulkBar = function () {
    var n = scwin.selectedList().length;
    scwin.toggleClass(grp_bulk, "is-open", n > 0);
    tbx_bulkCount.setValue("Đã chọn " + scwin.fmtNumber(n) + " khách");
};
scwin.btn_bulkClear_onclick = function () {
    scwin.selected = {};
    for (var i = 0; i < dlt_guest.getRowCount(); i++) dlt_guest.setCellData(i, "chk", "0");
    scwin.renderBulkBar();
};
scwin.btn_bulkPage_onclick = function () {
    for (var i = 0; i < dlt_guest.getRowCount(); i++) dlt_guest.setCellData(i, "chk", "1");
    scwin.syncSelection();
};

/* ---------- Thao tác trên dòng ---------- */
scwin.grd_guest_oncellclick = function (rowIndex, colIndex, colId) {
    var r = scwin.row(rowIndex);
    if (!r.guestId) return;
    if (colId === "chk") { scwin.debounce("sel", scwin.syncSelection, 50); return; }
    if (colId === "actEdit" && scwin.can("GUEST_UPDATE")) { scwin.editGuest(r.guestId); return; }
    if (colId === "actDelete" && scwin.can("GUEST_DELETE")) { scwin.openDelete([{ guestId: r.guestId, fullName: r.fullName, checkedIn: scwin.isTrue(r.checkedIn) }]); return; }
    if (colId === "actPrint" && scwin.can("PRINT_BADGE")) { scwin.quickPrint(r.guestId, r.fullName); return; }
    scwin.openDetail(r.guestId);
};

/** In nhanh thẻ tên 1 khách: server trả PDF và tự đánh dấu đã in. */
scwin.quickPrint = function (guestId, name, printType) {
    scwin.toast("Đang tạo bản in cho " + (name || "khách") + "…", "info");
    return scwin.xhr("POST", scwin.PRINT_API + "/quick", { body: { guestId: Number(guestId), printType: printType || "NAMECARD" }, responseType: "blob" })
        .then(function (r) {
            scwin.printBlob(r.blob);
            scwin.toast("Đã gửi thẻ tên của " + (name || "khách") + " tới hộp thoại in.", "success");
            scwin.search(false);
            if (scwin.current && String(scwin.current.guestId) === String(guestId)) scwin.openDetail(guestId, true);
        }).catch(function (err) { scwin.toast(err.message, "error"); });
};

scwin.btn_bulkPrint_onclick = function () {
    var list = scwin.selectedList();
    var events = {};
    list.forEach(function (g) { events[g.eventId] = true; });
    var ids = Object.keys(events);
    if (ids.length > 1) { scwin.toast("Các khách đã chọn thuộc nhiều sự kiện. Hãy lọc theo một sự kiện rồi chọn lại để in.", "warning"); return; }
    try {
        window.sessionStorage.setItem(scwin.HANDOFF_KEY, JSON.stringify({
            eventId: ids[0], printType: "NAMECARD",
            guests: list.map(function (g) { return { guestId: g.guestId, fullName: g.fullName }; })
        }));
    } catch (e) { }
    window.location.href = scwin.pageUrl(scwin.PRINT_PAGE, { eventId: ids[0] });
};

scwin.btn_import_onclick = function () { window.location.href = scwin.pageUrl(scwin.IMPORT_PAGE, { eventId: dma_search.get("eventId") }); };
scwin.btn_emptyImport_onclick = scwin.btn_import_onclick;

/* =====================================================================
 * CHI TIẾT KHÁCH
 * ===================================================================== */
scwin.openDetail = function (guestId, keepTab) {
    scwin.open.drawer = true;
    grp_drawerMask.addClass("is-open");
    grp_drawer.addClass("is-open");
    grp_drawer.addClass("is-loading");
    return scwin.callApi("sbm_guestDetail", { url: scwin.GUEST_API + "/" + guestId }).then(function (g) {
        scwin.renderDetail(g);
        scwin.setTab(keepTab ? scwin.tab : "info");
    }).catch(function (err) {
        scwin.toast(err.message, "error");
        if (err.status === 404) { scwin.closeDrawer(); scwin.search(false); }
    }).then(function () { grp_drawer.removeClass("is-loading"); });
};

scwin.renderDetail = function (g) {
    scwin.current = g;
    var ev = g.event || {}, type = g.guestType || {}, st = g.status || {}, ci = g.checkIn || {};
    var drawer = scwin.domOf(grp_drawer);
    if (drawer) {
        drawer.style.setProperty("--gs-status", scwin.safeColor(st.color));
        drawer.style.setProperty("--gs-type", scwin.safeColor(type.color));
    }
    tbx_dName.setValue(g.fullName || "");
    tbx_dType.setValue(scwin.typeName(type.code));
    tbx_dStatus.setValue(scwin.statusName(st.code));
    tbx_dEvent.setValue((ev.eventCode ? ev.eventCode + " - " : "") + (ev.eventName || ""));
    tbx_dInitial.setValue(scwin.initials(g.fullName));

    tbx_oEmail.setValue(scwin.dash(g.email));
    tbx_oPhone.setValue(scwin.dash(g.phone));
    tbx_oCompany.setValue(scwin.dash(g.company));
    tbx_oPosition.setValue(scwin.dash(g.position));
    tbx_oTable.setValue(g.tableNumber ? "Bàn " + g.tableNumber : "Chưa xếp bàn");
    tbx_oPrinted.setValue((g.badgePrinted ? "Đã in thẻ tên" : "Chưa in thẻ tên") + ", " + (g.nameplacePrinted ? "đã in danh bạ" : "chưa in danh bạ"));
    tbx_oNotes.setValue(g.notes || "Không có ghi chú.");
    scwin.toggleClass(tbx_oNotes, "is-placeholder", !g.notes);
    var cb = g.createdBy || {}, ub = g.updatedBy || {};
    tbx_oCreated.setValue("Thêm bởi " + (cb.fullName || cb.username || "—") + " lúc " + scwin.fmtDateTime(g.createdAt)
        + (g.importBatchId ? " (import #" + g.importBatchId + ")" : ""));
    tbx_oUpdated.setValue("Cập nhật bởi " + (ub.fullName || ub.username || "—") + " lúc " + scwin.fmtDateTime(g.updatedAt));

    // Ảnh khách
    if (g.photoUrl) { grp_photo.setStyle("background-image", "url(\"" + g.photoUrl + "\")"); grp_photo.addClass("has-image"); }
    else { grp_photo.setStyle("background-image", "none"); grp_photo.removeClass("has-image"); }
    scwin.show(btn_photoRemove, !!g.photoUrl);

    // Check-in
    var by = ci.checkedInBy || {};
    tbx_ciState.setValue(ci.checkedIn
        ? "Đã check-in lúc " + scwin.fmtDateTime(ci.checkInTime) + (by.fullName || by.username ? " (" + (by.fullName || by.username) + ")" : "")
        : "Khách chưa check-in.");
    scwin.toggleClass(grp_ciBox, "is-done", !!ci.checkedIn);
    scwin.show(btn_ciDo, !ci.checkedIn && scwin.canAny(["CHECKIN_SCAN", "GUEST_UPDATE"]));
    scwin.show(btn_ciCancel, !!ci.checkedIn && scwin.can("GUEST_UPDATE"));

    // QR
    var qr = g.qr || {};
    if (qr.imageDataUri) { grp_qrImg.setStyle("background-image", "url(\"" + qr.imageDataUri + "\")"); grp_qrImg.addClass("has-image"); }
    else { grp_qrImg.setStyle("background-image", "none"); grp_qrImg.removeClass("has-image"); }
    tbx_qrToken.setValue(qr.checkInToken || "—");
    tbx_qrGenerated.setValue(qr.generatedAt ? "Tạo lúc " + scwin.fmtDateTime(qr.generatedAt) : "");

    // Lịch sử
    var ck = g.checkInHistory || [], pr = g.printHistory || [];
    dlt_ckLog.setJSON(ck);
    for (var i = 0; i < ck.length; i++) {
        try { grd_ckLog.setCellClass(i, "result", "gs-res gs-res--" + (ck[i].cancelled ? "CANCELLED" : ck[i].result)); } catch (e) { }
    }
    scwin.fitGrid(grd_ckLog, ck.length, 48);
    scwin.show(grp_ckEmpty, !ck.length);
    tbx_ckCount.setValue(ck.length ? ck.length + " lần quét, mới nhất trước" : "");
    dlt_prLog.setJSON(pr);
    scwin.fitGrid(grd_prLog, pr.length, 48);
    scwin.show(grp_prEmpty, !pr.length);
    tbx_prCount.setValue(pr.length ? pr.length + " lần in" : "");
    btn_tabCheckins.setValue("Lịch sử check-in" + (ck.length ? " (" + ck.length + ")" : ""));
    btn_tabPrints.setValue("Lịch sử in" + (pr.length ? " (" + pr.length + ")" : ""));
    scwin.applyPermissions();
};

scwin.initials = function (name) {
    var w = scwin.trim(name).split(/\s+/).filter(function (x) { return !!x; });
    if (!w.length) return "?";
    return (w[0].charAt(0) + (w.length > 1 ? w[w.length - 1].charAt(0) : "")).toUpperCase();
};

scwin.setTab = function (tab) {
    if (!scwin.TABS[tab]) tab = "info";
    scwin.tab = tab;
    for (var k in scwin.TABS) {
        if (!scwin.TABS.hasOwnProperty(k)) continue;
        scwin.toggleClass(scwin.comp(scwin.TABS[k][0]), "is-selected", k === tab);
        scwin.show(scwin.comp(scwin.TABS[k][1]), k === tab);
    }
};
scwin.btn_tabInfo_onclick = function () { scwin.setTab("info"); };
scwin.btn_tabQr_onclick = function () { scwin.setTab("qr"); };
scwin.btn_tabCheckins_onclick = function () { scwin.setTab("checkins"); };
scwin.btn_tabPrints_onclick = function () { scwin.setTab("prints"); };

scwin.closeDrawer = function () {
    scwin.open.drawer = false;
    grp_drawerMask.removeClass("is-open");
    grp_drawer.removeClass("is-open");
};
scwin.grp_drawerMask_onclick = scwin.closeDrawer;
scwin.btn_dClose_onclick = scwin.closeDrawer;
scwin.btn_dEdit_onclick = function () { if (scwin.current) scwin.openForm("update", scwin.current); };
scwin.btn_dDelete_onclick = function () {
    var g = scwin.current;
    if (g) scwin.openDelete([{ guestId: g.guestId, fullName: g.fullName, checkedIn: !!(g.checkIn && g.checkIn.checkedIn) }]);
};
scwin.btn_dPrint_onclick = function () { if (scwin.current) scwin.quickPrint(scwin.current.guestId, scwin.current.fullName); };

scwin.gfMethod = function (v) { return scwin.METHOD_VN[v] || v || "—"; };
scwin.gfResult = function (v, f, i) {
    var r = dlt_ckLog.getRowJSON(i) || {};
    return (scwin.RESULT_VN[v] || v) + (scwin.isTrue(r.cancelled) ? " (đã hủy)" : "");
};
scwin.gfCkNote = function (v, f, i) {
    var r = dlt_ckLog.getRowJSON(i) || {};
    if (scwin.isTrue(r.cancelled)) return "Hủy bởi " + (r.cancelledByName || "—") + (r.cancelReason ? ": " + r.cancelReason : "");
    return [r.deviceInfo, r.note].filter(function (x) { return !!x; }).join(", ") || "—";
};
scwin.gfPrintType = function (v, f, i) {
    var r = dlt_prLog.getRowJSON(i) || {};
    return (scwin.PRINT_TYPE_VN[v] || v) + (scwin.isTrue(r.reprint) ? " (in lại)" : "");
};

/* ---------- Check-in thủ công / hủy check-in ---------- */
scwin.btn_ciDo_onclick = function () {
    scwin.openNote({
        title: "Check-in thủ công", label: "Ghi chú (không bắt buộc)", placeholder: "Ví dụ: khách quên thẻ",
        okText: "Check-in", onOk: function (note) {
            var g = scwin.current;
            return scwin.callApi("sbm_checkIn", { url: scwin.GUEST_API + "/" + g.guestId + "/check-in", body: note ? { note: note } : {} })
                .then(function (d) { scwin.renderDetail(d); scwin.toast("Đã check-in cho " + d.fullName + ".", "success"); scwin.search(false); });
        }
    });
};
scwin.btn_ciCancel_onclick = function () {
    scwin.openNote({
        title: "Hủy check-in", label: "Lý do hủy", placeholder: "Ví dụ: check-in nhầm người", danger: true,
        okText: "Hủy check-in", onOk: function (note) {
            var g = scwin.current;
            return scwin.callApi("sbm_cancelCheckIn", { url: scwin.GUEST_API + "/" + g.guestId + "/cancel-check-in", body: note ? { note: note } : {} })
                .then(function (d) { scwin.renderDetail(d); scwin.toast("Đã hủy check-in, khách về trạng thái Đã xác nhận.", "success"); scwin.search(false); });
        }
    });
};

/* ---------- Ảnh khách ---------- */
scwin.initFileInput = function () {
    var inp = document.createElement("input");
    inp.type = "file";
    inp.accept = scwin.PHOTO_TYPES.join(",");
    inp.className = "gs-native-file";
    inp.addEventListener("change", function () { var f = inp.files && inp.files[0]; inp.value = ""; if (f) scwin.uploadPhoto(f); });
    document.body.appendChild(inp);
    scwin.fileInput = inp;
};
scwin.btn_photoPick_onclick = function () { if (scwin.fileInput) scwin.fileInput.click(); };
scwin.uploadPhoto = function (file) {
    if (scwin.PHOTO_TYPES.indexOf(file.type) < 0) { scwin.toast("Ảnh khách chỉ nhận JPG hoặc PNG.", "warning"); return; }
    if (file.size > scwin.PHOTO_MAX) { scwin.toast("Ảnh nặng " + scwin.fmtSize(file.size) + ", tối đa 2 MB.", "warning"); return; }
    var g = scwin.current, fd = new FormData();
    fd.append("file", file);
    grp_photo.addClass("is-loading");
    scwin.xhr("POST", scwin.GUEST_API + "/" + g.guestId + "/photo", { body: fd }).then(function (d) {
        scwin.renderDetail(d); scwin.toast("Đã cập nhật ảnh khách.", "success");
    }).catch(function (err) { scwin.toast(err.message, "error"); })
      .then(function () { grp_photo.removeClass("is-loading"); });
};
scwin.btn_photoRemove_onclick = function () {
    var g = scwin.current;
    scwin.openConfirm({ title: "Gỡ ảnh khách?", message: "Thẻ tên in sau này sẽ không còn ảnh.", okText: "Gỡ ảnh", danger: true, onOk: function () {
        scwin.callApi("sbm_photoDelete", { url: scwin.GUEST_API + "/" + g.guestId + "/photo" }).then(function (d) {
            scwin.renderDetail(d); scwin.toast("Đã gỡ ảnh.", "success");
        }).catch(function (err) { scwin.toast(err.message, "error"); });
    } });
};

/* ---------- Mã QR ---------- */
scwin.qrUrl = function (format, download) {
    return scwin.GUEST_API + "/" + scwin.current.guestId + "/qr?" + scwin.buildQuery({ format: format, size: sbx_qrSize.getValue() || "512", download: download ? "true" : "false" });
};
scwin.btn_qrPng_onclick = function () { scwin.downloadFile(scwin.qrUrl("png", true), "QR-" + scwin.current.guestId + ".png", btn_qrPng); };
scwin.btn_qrSvg_onclick = function () { scwin.downloadFile(scwin.qrUrl("svg", true), "QR-" + scwin.current.guestId + ".svg", btn_qrSvg); };
scwin.btn_qrPrint_onclick = function () {
    var g = scwin.current, qr = (g && g.qr) || {};
    if (!qr.imageDataUri) return;
    var w = window.open("", "_blank", "width=640,height=760");
    if (!w) { scwin.toast("Trình duyệt đã chặn cửa sổ in. Hãy cho phép cửa sổ bật lên.", "warning"); return; }
    var e = scwin.escHtml;
    w.document.write("<!doctype html><html><head><meta charset='utf-8'><title>QR " + e(g.fullName) + "</title>"
        + "<style>body{font-family:Arial,sans-serif;text-align:center;padding:36px;color:#16241d}img{width:300px;height:300px}h1{font-size:22px;margin:14px 0 4px}p{margin:4px 0;color:#63746b}</style></head><body>"
        + "<img src='" + qr.imageDataUri + "' alt='QR'><h1>" + e(g.fullName) + "</h1><p>" + e(g.company || "") + "</p><p>" + e((g.event || {}).eventName || "") + "</p>"
        + "<script>setTimeout(function(){window.print();},300);<\/script></body></html>");
    w.document.close();
};
scwin.btn_qrRegen_onclick = function () {
    var g = scwin.current;
    scwin.openConfirm({
        title: "Tạo lại mã QR?",
        message: "Mã QR mới sẽ thay thế mã cũ. Thẻ tên đã in trước đó sẽ không quét được nữa, cần in lại thẻ cho khách.",
        okText: "Tạo mã mới", danger: true, onOk: function () {
            btn_qrRegen.addClass("is-busy");
            scwin.callApi("sbm_qrRegen", { url: scwin.GUEST_API + "/" + g.guestId + "/qr" }).then(function (d) {
                scwin.renderDetail(d); scwin.setTab("qr");
                scwin.toast("Đã tạo mã QR mới.", "success"); scwin.showWarnings(d.warnings);
            }).catch(function (err) { scwin.toast(err.message, "error"); })
              .then(function () { btn_qrRegen.removeClass("is-busy"); });
        }
    });
};

/* =====================================================================
 * FORM THÊM / SỬA
 * ===================================================================== */
scwin.btn_add_onclick = function () { scwin.openForm("create", null); };
scwin.btn_emptyAdd_onclick = scwin.btn_add_onclick;
scwin.editGuest = function (guestId) {
    scwin.callApi("sbm_guestDetail", { url: scwin.GUEST_API + "/" + guestId }).then(function (g) { scwin.openForm("update", g); })
        .catch(function (err) { scwin.toast(err.message, "error"); });
};

scwin.openForm = function (mode, g) {
    var f = scwin.form;
    f.mode = mode; f.guestId = g ? g.guestId : null; f.dirty = false; f.saving = false;
    f.origStatus = g && g.status ? g.status.code : "";
    var ev = (g && g.event) || {};
    dma_guestForm.setJSON({
        eventId: g ? String(ev.eventId) : (dma_search.get("eventId") || ""),
        fullName: g ? g.fullName || "" : "", email: g ? g.email || "" : "", phone: g ? g.phone || "" : "",
        company: g ? g.company || "" : "", position: g ? g.position || "" : "",
        guestTypeCode: g && g.guestType ? g.guestType.code : "GUEST", tableNumber: g ? g.tableNumber || "" : "",
        statusCode: g ? f.origStatus : "INVITED", notes: g ? g.notes || "" : ""
    });
    tbx_fTitle.setValue(mode === "create" ? "Thêm khách mời" : "Sửa thông tin khách");
    tbx_fSubtitle.setValue(mode === "create"
        ? "Họ tên và sự kiện là bắt buộc. Mã QR cá nhân được tạo ngay khi lưu."
        : "Đổi tên hoặc email không làm thay đổi mã QR, thẻ đã in vẫn quét được.");
    scwin.show(btn_fSaveNext, mode === "create");
    scwin.clearFormErrors();
    scwin.updateStatusHint();
    scwin.updateNotesCount();
    scwin.show(tbx_fEmailHint, false);
    scwin.open.form = true;
    grp_formMask.addClass("is-open");
    setTimeout(function () { try { (mode === "create" && !dma_guestForm.get("eventId") ? sbx_fEvent : ibx_fName).focus(); } catch (e) { } }, 150);
};
scwin.closeForm = function (force) {
    if (!force && scwin.form.dirty && !window.confirm("Thông tin vừa nhập chưa được lưu. Đóng biểu mẫu?")) return;
    scwin.open.form = false;
    grp_formMask.removeClass("is-open");
};
scwin.btn_fClose_onclick = function () { scwin.closeForm(false); };
scwin.btn_fCancel_onclick = function () { scwin.closeForm(false); };
scwin.markDirty = function () { scwin.form.dirty = true; };

scwin.syncFormInputs = function () {
    for (var k in scwin.FIELDS) {
        if (!scwin.FIELDS.hasOwnProperty(k)) continue;
        var c = scwin.comp(scwin.FIELDS[k].input);
        if (!c || !c.getValue) continue;
        var v = c.getValue();
        if (v != null && dma_guestForm.get(k) !== v) dma_guestForm.set(k, v);
    }
};
scwin.readForm = function () {
    var raw = dma_guestForm.getJSON(), v = {};
    for (var k in scwin.FIELDS) if (scwin.FIELDS.hasOwnProperty(k)) v[k] = scwin.trim(raw[k]);
    v.email = v.email.toLowerCase();
    return v;
};
scwin.validateForm = function (v) {
    var e = {};
    if (!v.eventId) e.eventId = "Chọn sự kiện cho khách.";
    if (!v.fullName) e.fullName = "Nhập họ và tên.";
    if (v.email && !scwin.EMAIL_RE.test(v.email)) e.email = "Email không đúng định dạng.";
    if (v.phone && !scwin.PHONE_RE.test(v.phone)) e.phone = "Số điện thoại 8–20 ký tự, chỉ gồm số, khoảng trắng, . ( ) - và dấu + ở đầu.";
    for (var k in scwin.FIELDS) {
        var fd = scwin.FIELDS[k];
        if (!e[k] && fd.max && v[k].length > fd.max) e[k] = fd.label + " tối đa " + scwin.fmtNumber(fd.max) + " ký tự.";
    }
    return e;
};
scwin.showFieldError = function (key, msg) {
    var fd = scwin.FIELDS[key];
    if (!fd) return false;
    var err = scwin.comp(fd.error);
    err.setValue(msg); scwin.show(err, true);
    scwin.comp(fd.input).addClass("is-invalid");
    return true;
};
scwin.clearFieldError = function (key) {
    var fd = scwin.FIELDS[key];
    if (!fd) return;
    scwin.show(scwin.comp(fd.error), false);
    scwin.comp(fd.input).removeClass("is-invalid");
};
scwin.clearFormErrors = function () {
    for (var k in scwin.FIELDS) if (scwin.FIELDS.hasOwnProperty(k)) scwin.clearFieldError(k);
    scwin.show(tbx_fAlert, false);
};

scwin.btn_fSave_onclick = function () { scwin.submitForm(false); };
scwin.btn_fSaveNext_onclick = function () { scwin.submitForm(true); };

scwin.submitForm = function (keepOpen) {
    var f = scwin.form;
    if (f.saving) return;
    scwin.syncFormInputs();
    scwin.clearFormErrors();
    var v = scwin.readForm(), errs = scwin.validateForm(v), keys = Object.keys(errs);
    if (keys.length) {
        keys.forEach(function (k) { scwin.showFieldError(k, errs[k]); });
        try { scwin.comp(scwin.FIELDS[keys[0]].input).focus(); } catch (e) { }
        return;
    }
    var body = {
        eventId: Number(v.eventId), fullName: v.fullName, email: v.email || null, phone: v.phone || null,
        company: v.company || null, position: v.position || null, guestTypeCode: v.guestTypeCode || null,
        tableNumber: v.tableNumber || null, notes: v.notes || null,
        statusCode: v.statusCode || (f.mode === "create" ? "INVITED" : null)
    };
    var mode = f.mode;
    scwin.setSaving(true);
    (mode === "create"
        ? scwin.callApi("sbm_guestCreate", { url: scwin.GUEST_API, body: body })
        : scwin.callApi("sbm_guestUpdate", { url: scwin.GUEST_API + "/" + f.guestId, body: body })
    ).then(function (g) {
        scwin.form.dirty = false;
        scwin.showWarnings(g.warnings);
        scwin.search(false);
        if (mode === "create" && keepOpen) {
            scwin.toast("Đã thêm " + g.fullName + ". Nhập tiếp khách khác.", "success");
            var keep = dma_guestForm.getJSON();
            dma_guestForm.setJSON({ eventId: keep.eventId, fullName: "", email: "", phone: "", company: keep.company, position: "",
                guestTypeCode: keep.guestTypeCode, tableNumber: "", statusCode: keep.statusCode, notes: "" });
            scwin.show(tbx_fEmailHint, false);
            setTimeout(function () { try { ibx_fName.focus(); } catch (e) { } }, 50);
            return;
        }
        scwin.closeForm(true);
        scwin.toast(mode === "create" ? "Đã thêm " + g.fullName + " và tạo mã QR cá nhân." : "Đã lưu thay đổi cho " + g.fullName + ".", "success");
        if (mode === "create" || (scwin.open.drawer && scwin.current && scwin.current.guestId === g.guestId)) {
            scwin.open.drawer = true;
            grp_drawerMask.addClass("is-open"); grp_drawer.addClass("is-open");
            scwin.renderDetail(g);
            if (mode === "create") scwin.setTab("info");
        }
    }).catch(function (err) { scwin.handleFormError(err); })
      .then(function () { scwin.setSaving(false); });
};

scwin.handleFormError = function (err) {
    var map = { GUEST_EMAIL_EXISTS: "email", INVALID_GUEST_TYPE: "guestTypeCode", INVALID_GUEST_STATUS: "statusCode", GUEST_CHECKED_IN: "eventId", EVENT_NOT_FOUND: "eventId" };
    var shown = false, first = null;
    if (err.code === "VALIDATION_ERROR" && err.data && typeof err.data === "object") {
        for (var k in err.data) if (err.data.hasOwnProperty(k) && scwin.showFieldError(k, err.data[k])) { shown = true; if (!first) first = k; }
    } else if (map[err.code]) {
        shown = scwin.showFieldError(map[err.code], err.message); first = map[err.code];
    }
    if (first) { try { scwin.comp(scwin.FIELDS[first].input).focus(); } catch (e) { } }
    if (!shown) { tbx_fAlert.setValue(err.message || "Không lưu được khách."); scwin.show(tbx_fAlert, true); }
};
scwin.setSaving = function (on) {
    scwin.form.saving = on;
    scwin.toggleClass(btn_fSave, "is-busy", on);
    try { btn_fSave.setDisabled(on); btn_fSaveNext.setDisabled(on); } catch (e) { }
};

/* ---------- Gợi ý trong form ---------- */
scwin.updateStatusHint = function () {
    var s = sbx_fStatus.getValue() || dma_guestForm.get("statusCode"), o = scwin.form.origStatus, msg = "";
    if (scwin.form.mode === "create" && s === "CHECKED_IN") msg = "Khách sẽ được check-in thủ công ngay khi lưu.";
    else if (scwin.form.mode === "update" && s === "CHECKED_IN" && o !== "CHECKED_IN") msg = "Lưu sẽ ghi nhận check-in thủ công cho khách.";
    else if (scwin.form.mode === "update" && o === "CHECKED_IN" && s !== "CHECKED_IN") msg = "Lưu sẽ hủy lượt check-in hiện tại của khách.";
    tbx_fStatusHint.setValue(msg);
    scwin.show(tbx_fStatusHint, !!msg);
};
scwin.updateNotesCount = function () {
    var n = (txa_fNotes.getValue() || "").length;
    tbx_fNotesCount.setValue(scwin.fmtNumber(n) + " / 2.000");
    scwin.toggleClass(tbx_fNotesCount, "is-over", n > 2000);
};
scwin.field_onkeyup = function (e) {
    scwin.markDirty();
    var t = e && e.target, id = t && (t.id || "");
    for (var k in scwin.FIELDS) if (scwin.FIELDS.hasOwnProperty(k) && id.indexOf(scwin.FIELDS[k].input) >= 0) scwin.clearFieldError(k);
};
scwin.ibx_fName_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("fullName"); };
scwin.ibx_fPhone_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("phone"); };
scwin.ibx_fEmail_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("email"); scwin.show(tbx_fEmailHint, false); };
scwin.txa_fNotes_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("notes"); scwin.updateNotesCount(); };
scwin.sbx_fStatus_onchange = function () { scwin.markDirty(); scwin.clearFieldError("statusCode"); scwin.updateStatusHint(); };
scwin.sbx_fEvent_onchange = function () { scwin.markDirty(); scwin.clearFieldError("eventId"); scwin.ibx_fEmail_onblur(); };
scwin.sbx_fType_onchange = function () { scwin.markDirty(); scwin.clearFieldError("guestTypeCode"); };

/** Kiểm tra trùng email trong sự kiện ngay khi rời ô (server vẫn kiểm tra lại khi lưu). */
scwin.ibx_fEmail_onblur = function () {
    scwin.syncFormInputs();
    var email = scwin.trim(dma_guestForm.get("email")).toLowerCase(), eventId = dma_guestForm.get("eventId");
    if (!email || !eventId || !scwin.EMAIL_RE.test(email)) { scwin.show(tbx_fEmailHint, false); return; }
    scwin.callApi("sbm_emailCheck", { url: scwin.GUEST_API + "?" + scwin.buildQuery({ eventId: eventId, email: email, size: 10 }) }).then(function (page) {
        if (scwin.trim(dma_guestForm.get("email")).toLowerCase() !== email) return;
        var dup = ((page && page.content) || []).filter(function (g) { return String(g.email).toLowerCase() === email && g.guestId !== scwin.form.guestId; })[0];
        tbx_fEmailHint.setValue(dup ? "Email này đã thuộc khách " + dup.fullName + " trong sự kiện." : "Email chưa có trong sự kiện.");
        scwin.toggleClass(tbx_fEmailHint, "is-warning", !!dup);
        scwin.toggleClass(tbx_fEmailHint, "is-ok", !dup);
        scwin.show(tbx_fEmailHint, true);
    }).catch(function () { scwin.show(tbx_fEmailHint, false); });
};

/* =====================================================================
 * CẬP NHẬT HÀNG LOẠT
 * ===================================================================== */
scwin.btn_bulkEdit_onclick = function () {
    var n = scwin.selectedList().length;
    if (!n) return;
    tbx_bTitle.setValue("Sửa " + scwin.fmtNumber(n) + " khách cùng lúc");
    sbx_bType.setValue(""); sbx_bStatus.setValue("");
    ibx_bTable.setValue(""); ibx_bCompany.setValue(""); ibx_bPosition.setValue(""); txa_bNotes.setValue("");
    chk_bClear.setValue("");
    scwin.show(tbx_bAlert, false); scwin.show(tbx_bResult, false);
    scwin.open.bulk = true;
    grp_bulkMask.addClass("is-open");
};
scwin.closeBulk = function () { scwin.open.bulk = false; grp_bulkMask.removeClass("is-open"); };
scwin.btn_bCancel_onclick = scwin.closeBulk;
scwin.btn_bClose_onclick = scwin.closeBulk;
scwin.btn_bSave_onclick = function () {
    var clear = String(chk_bClear.getValue() || "").split(/[\s,]+/).filter(function (x) { return !!x; });
    var body = { guestIds: scwin.selectedList().map(function (g) { return Number(g.guestId); }) };
    var any = false;
    if (sbx_bType.getValue()) { body.guestTypeCode = sbx_bType.getValue(); any = true; }
    if (sbx_bStatus.getValue()) { body.statusCode = sbx_bStatus.getValue(); any = true; }
    [["tableNumber", ibx_bTable], ["company", ibx_bCompany], ["position", ibx_bPosition], ["notes", txa_bNotes]].forEach(function (p) {
        var v = scwin.trim(p[1].getValue());
        if (clear.indexOf(p[0]) >= 0) { body[p[0]] = ""; any = true; }
        else if (v) { body[p[0]] = v; any = true; }
        else body[p[0]] = null;
    });
    if (!any) { tbx_bAlert.setValue("Chọn ít nhất một thông tin cần đổi."); scwin.show(tbx_bAlert, true); return; }
    scwin.show(tbx_bAlert, false);
    btn_bSave.addClass("is-busy");
    scwin.callApi("sbm_bulkUpdate", { url: scwin.GUEST_API + "/bulk-update", body: body }).then(function (r) {
        scwin.search(false);
        if (!r.failed) { scwin.closeBulk(); scwin.toast("Đã cập nhật " + scwin.fmtNumber(r.succeeded) + " khách.", "success"); return; }
        tbx_bResult.setValue("Đã cập nhật " + r.succeeded + "/" + r.total + " khách. Không cập nhật được:\n" + scwin.failureText(r.failures));
        scwin.show(tbx_bResult, true);
    }).catch(function (err) { tbx_bAlert.setValue(err.message); scwin.show(tbx_bAlert, true); })
      .then(function () { btn_bSave.removeClass("is-busy"); });
};
scwin.failureText = function (failures) {
    return (failures || []).map(function (f) {
        var g = scwin.selected[f.guestId];
        return "• " + (g ? g.fullName : "Khách #" + f.guestId) + ": " + f.message;
    }).join("\n");
};

/* =====================================================================
 * XÓA (1 khách hoặc hàng loạt)
 * ===================================================================== */
scwin.btn_bulkDelete_onclick = function () { scwin.openDelete(scwin.selectedList()); };
scwin.openDelete = function (list) {
    if (!list.length) return;
    scwin.delList = list;
    var checked = list.filter(function (g) { return g.checkedIn; });
    tbx_delTitle.setValue(list.length === 1 ? "Xóa khách " + list[0].fullName + "?" : "Xóa " + scwin.fmtNumber(list.length) + " khách đã chọn?");
    tbx_delDesc.setValue("Khách sẽ bị ẩn khỏi danh sách (xóa mềm). Mã QR của khách không còn dùng được.");
    var warn = "";
    if (checked.length === list.length) warn = (list.length === 1 ? "Khách này đã check-in" : "Tất cả khách đã chọn đều đã check-in") + " nên không xóa được. Hãy hủy check-in trước nếu thật sự cần xóa.";
    else if (checked.length) warn = scwin.fmtNumber(checked.length) + " khách đã check-in sẽ được giữ lại, chỉ xóa " + scwin.fmtNumber(list.length - checked.length) + " khách còn lại.";
    tbx_delErr.setValue(warn);
    scwin.show(tbx_delErr, !!warn);
    scwin.toggleClass(grp_delModal, "is-blocked", checked.length === list.length);
    try { btn_delConfirm.setDisabled(checked.length === list.length); } catch (e) { }
    scwin.open.del = true;
    grp_delMask.addClass("is-open");
};
scwin.closeDelete = function () { scwin.open.del = false; grp_delMask.removeClass("is-open"); };
scwin.btn_delCancel_onclick = scwin.closeDelete;
scwin.btn_delConfirm_onclick = function () {
    var list = scwin.delList;
    btn_delConfirm.addClass("is-busy");
    var req = list.length === 1
        ? scwin.callApi("sbm_guestDelete", { url: scwin.GUEST_API + "/" + list[0].guestId + "?confirm=true" }).then(function () { return { total: 1, succeeded: 1, failed: 0 }; })
        : scwin.callApi("sbm_bulkDelete", { url: scwin.GUEST_API + "/bulk-delete", body: { guestIds: list.map(function (g) { return Number(g.guestId); }), confirm: true } });
    req.then(function (r) {
        var failedIds = {};
        (r.failures || []).forEach(function (f) { failedIds[f.guestId] = true; });
        list.forEach(function (g) { if (!failedIds[g.guestId]) delete scwin.selected[g.guestId]; });
        if (scwin.current && !failedIds[scwin.current.guestId] && list.some(function (g) { return String(g.guestId) === String(scwin.current.guestId); })) scwin.closeDrawer();
        scwin.search(false);
        if (!r.failed) { scwin.closeDelete(); scwin.toast("Đã xóa " + scwin.fmtNumber(r.succeeded) + " khách.", "success"); return; }
        tbx_delErr.setValue("Đã xóa " + r.succeeded + "/" + r.total + " khách. Không xóa được:\n" + scwin.failureText(r.failures));
        scwin.show(tbx_delErr, true);
        try { btn_delConfirm.setDisabled(true); } catch (e) { }
    }).catch(function (err) {
        tbx_delErr.setValue(err.code === "GUEST_CHECKED_IN" ? err.message : err.message);
        scwin.show(tbx_delErr, true);
    }).then(function () { btn_delConfirm.removeClass("is-busy"); });
};

/* =====================================================================
 * EXPORT
 * ===================================================================== */
scwin.exp = { format: "xlsx", cols: null };
scwin.btn_export_onclick = function () {
    scwin.open.exp = true;
    grp_expMask.addClass("is-open");
    var p = scwin.collectFilter(true);
    var n = scwin.fmtNumber(scwin.state.totalElements);
    tbx_xScope.setValue(scwin.hasFilter()
        ? "Xuất " + n + " khách theo bộ lọc đang áp dụng ở danh sách."
        : "Xuất toàn bộ " + n + " khách " + (p.eventId ? "của sự kiện đang chọn." : "của mọi sự kiện bạn được xem."));
    scwin.setExpFormat(scwin.exp.format);
    if (scwin.exp.cols) return;
    scwin.callApi("sbm_exportCols", { url: scwin.GUEST_API + "/export/columns" }).then(function (cols) {
        scwin.exp.cols = cols || [];
        dlt_expCols.setJSON(scwin.exp.cols.map(function (c) { return { key: c.key, label: c.label }; }));
        scwin.btn_xDefault_onclick();
    }).catch(function (err) { scwin.toast(err.message, "error"); });
};
scwin.closeExport = function () { scwin.open.exp = false; grp_expMask.removeClass("is-open"); };
scwin.btn_xCancel_onclick = scwin.closeExport;
scwin.btn_xClose_onclick = scwin.closeExport;
scwin.setExpFormat = function (f) {
    scwin.exp.format = f;
    scwin.toggleClass(btn_xXlsx, "is-selected", f === "xlsx");
    scwin.toggleClass(btn_xCsv, "is-selected", f === "csv");
    scwin.toggleClass(btn_xPdf, "is-selected", f === "pdf");
    tbx_xQrHint.setValue(f === "csv" ? "CSV: thêm cột “Nội dung QR” dạng chữ." : "Thêm ảnh mã QR vào từng dòng (tối đa 2.000 khách).");
};
scwin.btn_xXlsx_onclick = function () { scwin.setExpFormat("xlsx"); };
scwin.btn_xCsv_onclick = function () { scwin.setExpFormat("csv"); };
scwin.btn_xPdf_onclick = function () { scwin.setExpFormat("pdf"); };
scwin.btn_xAll_onclick = function () { chk_xCols.setValue((scwin.exp.cols || []).map(function (c) { return c.key; }).join(",")); };
scwin.btn_xNone_onclick = function () { chk_xCols.setValue(""); };
scwin.btn_xDefault_onclick = function () {
    chk_xCols.setValue((scwin.exp.cols || []).filter(function (c) { return c.defaultSelected; }).map(function (c) { return c.key; }).join(","));
};
scwin.btn_xRun_onclick = function () {
    var cols = String(chk_xCols.getValue() || "").split(/[\s,]+/).filter(function (x) { return !!x; });
    if (!cols.length) { scwin.toast("Chọn ít nhất một cột để xuất.", "warning"); return; }
    var p = scwin.collectFilter(true);
    p.format = scwin.exp.format;
    p.columns = cols;
    p.includeQr = String(chk_xQr.getValue() || "") ? "true" : "false";
    scwin.downloadFile(scwin.GUEST_API + "/export?" + scwin.buildQuery(p), "DanhSachKhach." + scwin.exp.format, btn_xRun)
        .then(function (r) { if (r) { scwin.closeExport(); scwin.toast("Đã xuất file " + (r.name || "") + ".", "success"); } });
};

/* =====================================================================
 * HỘP NHẬP GHI CHÚ & HỘP XÁC NHẬN DÙNG CHUNG
 * ===================================================================== */
scwin.openNote = function (o) {
    scwin.note = o;
    tbx_nTitle.setValue(o.title); tbx_nLabel.setValue(o.label);
    txa_note.setValue("");
    tbx_nHint.setValue(o.placeholder || "");
    btn_nOk.setValue(o.okText || "Xác nhận");
    scwin.toggleClass(btn_nOk, "gs-btn--danger", !!o.danger);
    scwin.toggleClass(btn_nOk, "gs-btn--primary", !o.danger);
    scwin.show(tbx_nErr, false);
    scwin.open.note = true;
    grp_noteMask.addClass("is-open");
    setTimeout(function () { try { txa_note.focus(); } catch (e) { } }, 120);
};
scwin.closeNote = function () { scwin.open.note = false; grp_noteMask.removeClass("is-open"); };
scwin.btn_nCancel_onclick = scwin.closeNote;
scwin.btn_nOk_onclick = function () {
    var o = scwin.note;
    if (!o) return;
    btn_nOk.addClass("is-busy");
    Promise.resolve(o.onOk(scwin.trim(txa_note.getValue()))).then(function () { scwin.closeNote(); })
        .catch(function (err) { tbx_nErr.setValue(err.message); scwin.show(tbx_nErr, true); })
        .then(function () { btn_nOk.removeClass("is-busy"); });
};

scwin.openConfirm = function (o) {
    scwin.cfm = o;
    tbx_cfmTitle.setValue(o.title || "Xác nhận");
    tbx_cfmMsg.setValue(o.message || "");
    btn_cfmOk.setValue(o.okText || "Đồng ý");
    scwin.toggleClass(btn_cfmOk, "gs-btn--danger", !!o.danger);
    scwin.toggleClass(btn_cfmOk, "gs-btn--primary", !o.danger);
    scwin.toggleClass(grp_cfmModal, "is-danger", !!o.danger);
    scwin.open.confirm = true;
    grp_cfmMask.addClass("is-open");
};
scwin.closeConfirm = function () { scwin.open.confirm = false; grp_cfmMask.removeClass("is-open"); };
scwin.btn_cfmCancel_onclick = function () { scwin.closeConfirm(); scwin.cfm = null; };
scwin.btn_cfmOk_onclick = function () { var o = scwin.cfm; scwin.closeConfirm(); scwin.cfm = null; if (o && o.onOk) o.onOk(); };

/* ---------- Phím tắt ---------- */
scwin.onGlobalKeydown = function (e) {
    if (e.key === "Escape") {
        if (scwin.open.confirm) scwin.btn_cfmCancel_onclick();
        else if (scwin.open.note) scwin.closeNote();
        else if (scwin.open.del) scwin.closeDelete();
        else if (scwin.open.exp) scwin.closeExport();
        else if (scwin.open.bulk) scwin.closeBulk();
        else if (scwin.open.form) scwin.closeForm(false);
        else if (scwin.open.drawer) scwin.closeDrawer();
        return;
    }
    if (scwin.open.form && e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
        scwin.submitForm(false);
        return;
    }
    var tag = (e.target && e.target.tagName || "").toLowerCase();
    if (e.key === "/" && tag !== "input" && tag !== "textarea" && !scwin.open.form) { e.preventDefault(); try { ibx_keyword.focus(); } catch (x) { } }
};

